import { existsSync, mkdirSync, readFileSync, readdirSync, renameSync, rmSync, writeFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { dirname, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { assertBuildOutput } from './build-outputs.mjs';

// Reuse existing generated bytes; replace changed files atomically for concurrent readers.
export function writeGeneratedFile(path, content) {
  const target = path instanceof URL ? fileURLToPath(path) : path;
  const bytes = Buffer.isBuffer(content) ? content : Buffer.from(content);
  if (existsSync(target) && readFileSync(target).equals(bytes)) return false;
  mkdirSync(dirname(target), { recursive: true });
  const temporary = `${target}.${randomUUID()}.tmp`;
  try { writeFileSync(temporary, bytes, { flag: 'wx' }); renameSync(temporary, target); }
  finally { rmSync(temporary, { force: true }); }
  return true;
}

export function copyGeneratedFile(source, target) {
  return writeGeneratedFile(target, readFileSync(source));
}

export function pruneGeneratedFiles(root, directory, expected, check = false) {
  const target = assertBuildOutput(root, directory);
  const names = new Set(expected.map(path => path.replaceAll('\\', '/')));
  if (!existsSync(target)) { if (check) throw new Error(`Missing generated directory: ${directory}`); return; }
  const obsolete = [];
  function walk(path) {
    for (const entry of readdirSync(path, { withFileTypes: true })) {
      const file = resolve(path, entry.name);
      if (entry.isSymbolicLink()) throw new Error(`Linked generated file: ${file}`);
      if (entry.isDirectory()) walk(file);
      else if (!names.has(relative(target, file).split(sep).join('/'))) obsolete.push(file);
    }
  }
  walk(target);
  if (check && obsolete.length) throw new Error(`Obsolete generated files: ${obsolete.map(path => relative(target, path)).join(', ')}`);
  for (const path of obsolete) rmSync(path);
}
